تا پایان تعمیر شاول ۳ حدود 40,000 تن در ماه کمبود تولید داریم. بین شیفت اضافه و پیمانکار استخراج کدام به‌صرفه‌تر است؟ (مدیر تولید معدن — معدن سنگ‌آهن سنگان)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "production_plan_actual",
      "description": "برنامه و واقعی استخراج به تفکیک پیت و هفته",
      "dimensions": [
        "pit",
        "week"
      ],
      "measures": [
        "plan_tons",
        "actual_tons"
      ]
    },
    {
      "dataset": "cost_ledger",
      "description": "هزینهٔ عملیاتی به تفکیک جزء (سوخت، قطعات، دستمزد، پیمانکار)",
      "dimensions": [
        "component",
        "period"
      ],
      "measures": [
        "toman_per_ton"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "extraction_rate",
      "description": "نرخ استخراج",
      "formula": "تن استخراج‌شده / روزهای کاری",
      "unit": "تن در روز",
      "dimensions": [
        "pit",
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با دو پیت فعال و کارخانهٔ فرآوری مجاور",
    "برنامهٔ تولید ماهانه و شاخص‌های فنی هفته‌به‌هفته به‌روز می‌شود"
  ]
}

