نقش سازمانی: مدیر تولید معدن (mining_production_manager)

درخواست کاربر:
این ماه تولید ما رشد کرده ولی توقف تجهیزات هم زیاد شده. سرپرست معدن می‌گوید تولید بیشتر باعث فرسودگی شده و باید تولید را کم کنیم. درست است؟ (مدیر تولید معدن — معدن زغال‌سنگ کرمان)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "production_plan_actual",
      "description": "برنامه و واقعی استخراج به تفکیک پیت و هفته",
      "dimensions": [
        "pit",
        "week"
      ],
      "measures": [
        "plan_tons",
        "actual_tons"
      ]
    },
    {
      "dataset": "equipment_downtime",
      "description": "ساعت توقف تجهیزات به تفکیک تجهیز و علت",
      "dimensions": [
        "equipment",
        "reason",
        "period"
      ],
      "measures": [
        "hours"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "extraction_rate",
      "description": "نرخ استخراج",
      "formula": "تن استخراج‌شده / روزهای کاری",
      "unit": "تن در روز",
      "dimensions": [
        "pit",
        "period"
      ]
    },
    {
      "metric": "equipment_downtime",
      "description": "توقف برنامه‌ریزی‌نشدهٔ تجهیزات",
      "formula": "مجموع ساعت توقف",
      "unit": "ساعت",
      "dimensions": [
        "equipment",
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با دو پیت فعال و کارخانهٔ فرآوری مجاور",
    "برنامهٔ تولید ماهانه و شاخص‌های فنی هفته‌به‌هفته به‌روز می‌شود"
  ]
}

