گزارش تحقق برنامهٔ استخراج این ماه را بده؛ کدام پیت عقب است و چقدر؟ (مدیر تولید معدن — مجتمع معدنی گل‌گهر)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "production_plan_actual",
      "description": "برنامه و واقعی استخراج به تفکیک پیت و هفته",
      "dimensions": [
        "pit",
        "week"
      ],
      "measures": [
        "plan_tons",
        "actual_tons"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "extraction_rate",
      "description": "نرخ استخراج",
      "formula": "تن استخراج‌شده / روزهای کاری",
      "unit": "تن در روز",
      "dimensions": [
        "pit",
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با دو پیت فعال و کارخانهٔ فرآوری مجاور",
    "برنامهٔ تولید ماهانه و شاخص‌های فنی هفته‌به‌هفته به‌روز می‌شود"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "production_plan_actual",
    "filters": {
      "period": "this_month"
    }
  }
}

